G=[[0]*22 for _ in range(23)]
def frame(r0,r1,c0,c1,col):
 for c in range(c0,c1+1): G[r0][c]=G[r1][c]=col
 for r in range(r0,r1+1): G[r][c0]=G[r][c1]=col
frame(2,6,2,9,5); frame(1,6,12,21,8); frame(8,12,11,18,1); frame(14,19,15,20,6); frame(18,21,4,12,3)
P=[[0,7,7,0,0,7],[7,7,0,7,7,7],[0,7,7,7,0,0]]
# paint interiors top-left crop
for r0,r1,c0,c1,col in [(2,6,2,9,5),(1,6,12,21,8),(8,12,11,18,1),(14,19,15,20,6),(18,21,4,12,3)]:
 for i,r in enumerate(range(r0+1,r1)):
  for j,c in enumerate(range(c0+1,c1)):
   if i<len(P) and j<len(P[0]) and P[i][j]:G[r][c]=col
print(G)
